    { "task": "prep", "maxConcurrent": 1 },
    { "task": "stovetop", "maxConcurrent": 2 }
  ],
  "metadata": {
    "serves": "2",
    "ingredients": [
      { "name": "jasmine rice", "measure": "1 cup" },
      { "name": "chicken thighs", "measure": "1 lb" },
      { "name": "broccoli", "measure": "1 head" },
      { "name": "garlic", "measure": "3 cloves" },
      { "name": "ginger", "measure": "1 thumb" },
      { "name": "soy sauce", "measure": "3 tbsp" },
      { "name": "oyster sauce", "measure": "1 tbsp" },
      { "name": "cornstarch", "measure": "1 tsp" },
      { "name": "sugar", "measure": "1 tsp" },
      { "name": "rice vinegar", "measure": "splash" },
      { "name": "oil", "measure": "for wok" }
    ]
  }
